    "corpo": [
      "O Sistema Único de Segurança Pública (SUSP), instituído pela Lei 13.675/2018, busca integrar a atuação dos órgãos de segurança pública das diferentes esferas federativas (União, Estados, Municípios), definindo princípios, diretrizes e objetivos comuns — é uma tentativa institucional de reduzir a fragmentação entre as polícias (relembre o ciclo de polícia bipartido, já visto em Direito Constitucional) e coordenar políticas nacionais de segurança.",
      "Entre os desafios estruturais recorrentes na segurança pública brasileira, frequentemente pautados em debates públicos e cobrados em prova: letalidade policial (o índice de mortes decorrentes de intervenção policial, e as políticas voltadas a reduzi-la, como uso de câmeras corporais e protocolos de uso da força), superlotação carcerária e o já estudado 'estado de coisas inconstitucional', expansão e atuação de facções criminosas com influência territorial, e o debate sobre municiamento e financiamento adequado das polícias estaduais.",
      "Esses temas estruturais são a base sobre a qual qualquer notícia específica de segurança pública vai se apoiar — ao entender o SUSP, a discussão sobre letalidade policial, e a relação entre política criminal e sistema prisional, o candidato consegue interpretar corretamente qualquer questão que traga uma notícia concreta sobre esses assuntos, mesmo sem tê-la acompanhado especificamente antes da prova."
    ],
    "pontosChave": [
      "SUSP (Lei 13.675/2018) busca integrar e coordenar as políticas de segurança pública entre as esferas federativas.",
      "Letalidade policial é debate recorrente, ligado a políticas como câmeras corporais e uso progressivo da força.",
      "Superlotação carcerária, expansão de facções e financiamento policial são desafios estruturais permanentes do tema."
    ],
