      "Desinformação (também popularmente chamada de 'fake news') é a disseminação deliberada ou não de informações falsas ou enganosas, amplificada pela velocidade e alcance das redes sociais — tema recorrente em debates sobre eleições, saúde pública e segurança, com desdobramentos jurídicos que se conectam ao crime de denunciação caluniosa e comunicação falsa de crime, já vistos em Direito Penal.",
      "Regulação de plataformas digitais é um debate estrutural permanente: até que ponto redes sociais e aplicativos de mensagem devem ser responsabilizados pelo conteúdo publicado por seus usuários, e quais mecanismos de moderação e transparência devem ser exigidos — envolve tensão entre liberdade de expressão (direito fundamental já estudado) e proteção contra danos coletivos (discurso de ódio, desinformação em massa, crimes contra a honra).",
      "Inclusão digital é outro tema estrutural relevante: o acesso desigual à internet e a dispositivos tecnológicos (a chamada 'exclusão digital') afeta o exercício de direitos sociais cada vez mais dependentes de serviços online (educação, saúde, acesso a benefícios sociais) — um tema que se conecta ao princípio do mínimo existencial, já visto no módulo de Direito Constitucional, quando aplicado ao contexto de conectividade."
