      "Cidadania, em sentido amplo, envolve o exercício pleno de direitos civis, políticos e sociais — debates contemporâneos sobre acesso à justiça, participação social e efetividade de políticas públicas (educação, saúde, segurança) sempre remetem a esse conceito mais amplo, já trabalhado de forma fragmentada nos módulos de Direito Constitucional (direitos sociais, direitos políticos) e Direitos Humanos (características e gerações de direitos).",
