      "O Maranhão está localizado na transição entre o Nordeste e a Amazônia, com território que abrange desde litoral (reentrâncias maranhenses, com destaque para São Luís, cidade insular) até áreas de cerrado no sul do estado — essa diversidade geográfica é uma das características estruturais mais cobradas em prova estadual, já que a maioria das provas de nível médio explora conhecimento local com maior profundidade do que conhecimento nacional genérico.",
      "Economicamente, o estado tem no Porto do Itaqui (em São Luís) um dos principais complexos portuários do país, com forte presença de exportação de minério de ferro (escoamento da produção de Carajás, no Pará, via Estrada de Ferro Carajás) e de grãos (soja) produzidos no sul do estado (região conhecida como Matopiba, que também abrange partes do Tocantins, Piauí e Bahia). Turismo é outro eixo econômico relevante, com destaque para os Lençóis Maranhenses (Parque Nacional com dunas de areia branca e lagoas de água da chuva) e o centro histórico de São Luís (Patrimônio Mundial da UNESCO).",
      "Indicadores sociais estruturais: o Maranhão historicamente apresenta desafios significativos em indicadores de desenvolvimento humano, educação e infraestrutura básica em comparação com a média nacional — esse é um tema estrutural relevante para compreensão de políticas públicas estaduais, mas os números específicos e sua evolução exigem consulta a fontes atualizadas (IBGE, PNUD) próximo à data da prova, já que mudam a cada nova pesquisa/censo."
